BEGIN TRANSACTION;
PRAGMA defer_foreign_keys=ON;
CREATE TABLE "account_access" ( "user_id" integer NOT NULL PRIMARY KEY, "version" integer NOT NULL DEFAULT 0, "suspended" boolean NOT NULL DEFAULT FALSE, FOREIGN KEY ("user_id") REFERENCES "users" ("id") ON DELETE RESTRICT );
CREATE TABLE "account_write_lock" ( "id" integer NOT NULL PRIMARY KEY, "version" integer NOT NULL );
CREATE TABLE "administrative_audit" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "actor_id" integer NOT NULL, "target_type" varchar(40) NOT NULL, "target_id" varchar(64) NOT NULL, "action" varchar(64) NOT NULL, "summary" text NOT NULL, "created_at" integer NOT NULL , "actor_type" varchar NOT NULL DEFAULT 'user', "private_reason" text NULL);
CREATE TABLE "article_media" ( "id" text NOT NULL PRIMARY KEY, "owner_id" integer NOT NULL, "storage_key" text NOT NULL, "width" integer NOT NULL, "height" integer NOT NULL, "created_at" integer NOT NULL, FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE RESTRICT );
CREATE TABLE "article_revision_terms" ( "revision_id" integer NOT NULL, "term_id" integer NOT NULL, PRIMARY KEY ("revision_id", "term_id"), FOREIGN KEY ("revision_id") REFERENCES "article_revisions" ("id") ON DELETE RESTRICT, FOREIGN KEY ("term_id") REFERENCES "article_terms" ("id") ON DELETE RESTRICT );
CREATE TABLE "article_revisions" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "article_id" integer NOT NULL, "slug" text NOT NULL, "title" text NOT NULL, "summary" text NOT NULL, "search_text" text NOT NULL, "body" text NOT NULL, "media_id" text NULL, "media_alt" text NOT NULL, "created_at" integer NOT NULL, "seo" text NOT NULL DEFAULT '{}', FOREIGN KEY ("article_id") REFERENCES "articles" ("id") ON DELETE RESTRICT, FOREIGN KEY ("media_id") REFERENCES "article_media" ("id") ON DELETE RESTRICT );
CREATE TABLE "article_slugs" ( "slug" text NOT NULL PRIMARY KEY, "article_id" integer NOT NULL, FOREIGN KEY ("article_id") REFERENCES "articles" ("id") ON DELETE RESTRICT );
CREATE TABLE "article_terms" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "kind" text NOT NULL, "slug" text NOT NULL, "name" text NOT NULL, "active" boolean NOT NULL, "version" integer NOT NULL, "seo" text NOT NULL DEFAULT '{}', UNIQUE ("kind", "slug") );
CREATE TABLE "articles" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "author_id" integer NOT NULL, "slug" text NOT NULL, "version" integer NOT NULL, "current_revision_id" integer NULL, "published_revision_id" integer NULL, "published_at" integer NULL, "created_at" integer NOT NULL, "updated_at" integer NOT NULL, FOREIGN KEY ("author_id") REFERENCES "users" ("id") ON DELETE RESTRICT );
CREATE TABLE "auth_flow_tokens" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" text NOT NULL, "token_hash" varchar(64) NOT NULL UNIQUE, "purpose" text NOT NULL, "expires_at" datetime_text NOT NULL, "used_at" datetime_text NULL, "created_at" datetime_text NOT NULL );
CREATE TABLE "billing_settings" ( "mode" varchar(4) NOT NULL PRIMARY KEY, "revision" integer NOT NULL, "payload" text NOT NULL );
CREATE TABLE "demo_seed_state" ( "id" integer NOT NULL PRIMARY KEY, "version" integer NOT NULL, "completed" boolean NOT NULL );
CREATE TABLE "listing_categories" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "slug" varchar(140) NOT NULL UNIQUE, "name" varchar(120) NOT NULL, "active" boolean NOT NULL DEFAULT TRUE , "version" integer NOT NULL DEFAULT 0, "seo" text NOT NULL DEFAULT '{}');
CREATE TABLE "listing_media" ( "id" varchar(36) NOT NULL PRIMARY KEY, "owner_id" integer NOT NULL, "storage_key" varchar(40) NOT NULL UNIQUE, "width" integer NOT NULL, "height" integer NOT NULL, "created_at" integer NOT NULL, FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE RESTRICT );
CREATE TABLE "listing_revision_categories" ( "revision_id" integer NOT NULL, "category_id" integer NOT NULL, PRIMARY KEY ("revision_id", "category_id"), FOREIGN KEY ("revision_id") REFERENCES "listing_revisions" ("id") ON DELETE RESTRICT, FOREIGN KEY ("category_id") REFERENCES "listing_categories" ("id") ON DELETE RESTRICT );
CREATE TABLE "listing_revisions" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "listing_id" integer NOT NULL, "title" varchar(120) NOT NULL, "summary" varchar(280) NOT NULL, "search_text" text NOT NULL, "description" text NOT NULL, "url" text NOT NULL, "media_id" varchar(36), "media_alt" varchar(280) NOT NULL, "status" varchar(12) NOT NULL, "reason" text, "decided_by" integer, "decided_at" integer, "created_at" integer NOT NULL, "seo" text NOT NULL DEFAULT '{}', FOREIGN KEY ("listing_id") REFERENCES "listings" ("id") ON DELETE RESTRICT, FOREIGN KEY ("media_id") REFERENCES "listing_media" ("id") ON DELETE RESTRICT );
CREATE TABLE "listings" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "owner_id" integer NOT NULL, "slug" varchar(160) NOT NULL UNIQUE, "version" integer NOT NULL DEFAULT 0, "current_revision_id" integer, "approved_revision_id" integer, "archived" boolean NOT NULL DEFAULT FALSE, "suspended" boolean NOT NULL DEFAULT FALSE, "created_at" integer NOT NULL, FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE RESTRICT );
CREATE TABLE "model_has_permissions" ( "permission_id" integer NOT NULL, "model_type" varchar(255) NOT NULL, "model_id" integer NOT NULL, PRIMARY KEY ("permission_id", "model_id", "model_type"), FOREIGN KEY ("permission_id") REFERENCES "permissions" ("id") ON DELETE CASCADE );
CREATE TABLE "model_has_roles" ( "role_id" integer NOT NULL, "model_type" varchar(255) NOT NULL, "model_id" integer NOT NULL, PRIMARY KEY ("role_id", "model_id", "model_type"), FOREIGN KEY ("role_id") REFERENCES "roles" ("id") ON DELETE CASCADE );
CREATE TABLE "owner_notifications" ( "id" text NOT NULL PRIMARY KEY, "event_key" text NOT NULL, "title" text NOT NULL, "body" text NOT NULL, "path" text NOT NULL, "status" text NOT NULL, "owner_id" integer NOT NULL, "listing_id" integer NOT NULL, "attempts" integer NOT NULL, "next_attempt_at" integer NOT NULL, "created_at" integer NOT NULL, "purchase_id" text NULL, "lease_token" text NULL, "last_error" text NULL, "lease_until" integer NULL, "delivered_at" integer NULL );
CREATE TABLE "permissions" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "guard_name" varchar(255) NOT NULL, "created_at" datetime_text NULL, "updated_at" datetime_text NULL );
CREATE TABLE "publication_entitlements" ( "id" varchar(64) NOT NULL PRIMARY KEY, "listing_id" integer NOT NULL, "mode" varchar(8) NOT NULL, "status" varchar(16) NOT NULL, "valid_from" integer NOT NULL, "valid_until" integer, "updated_at" integer NOT NULL, FOREIGN KEY ("listing_id") REFERENCES "listings" ("id") ON DELETE RESTRICT );
CREATE TABLE "publishing_events" ( "id" text NOT NULL PRIMARY KEY, "provider" text NOT NULL, "mode" text NOT NULL, "provider_event_id" text NOT NULL, "event_type" text NOT NULL, "raw_body" blob(1) NOT NULL, "signature" text NOT NULL, "occurred_at" integer NOT NULL, "received_at" integer NOT NULL, "purchase_id" text NULL, "credential_source" text NOT NULL, "status" text NOT NULL, "attempts" integer NOT NULL, "next_attempt_at" integer NOT NULL, "error_code" text NULL, "lease_token" text NULL, "lease_until" integer NULL, "enrichment" text NULL, FOREIGN KEY ("purchase_id") REFERENCES "publishing_purchases" ("id") ON DELETE RESTRICT );
CREATE TABLE "publishing_payments" ( "id" text NOT NULL PRIMARY KEY, "purchase_id" text NOT NULL, "provider_payment_id" text NOT NULL, "amount_total" integer NOT NULL, "period_start" integer NOT NULL, "period_end" integer NULL, "status" text NOT NULL, "paid_at" integer NOT NULL, "refund_event_at" integer NOT NULL, "dispute_event_at" integer NOT NULL, "adverse" text NOT NULL, "created_at" integer NOT NULL, FOREIGN KEY ("purchase_id") REFERENCES "publishing_purchases" ("id") ON DELETE RESTRICT );
CREATE TABLE "publishing_plans" ( "key" text NOT NULL PRIMARY KEY, "name" text NOT NULL, "description" text NOT NULL, "enabled" boolean NOT NULL, "billing_type" text NOT NULL, "amount" integer NOT NULL, "currency" text NOT NULL, "version" integer NOT NULL, "created_at" integer NOT NULL, "updated_at" integer NOT NULL );
CREATE TABLE "publishing_purchases" ( "id" text NOT NULL PRIMARY KEY, "listing_id" integer NOT NULL, "owner_id" integer NOT NULL, "approved_revision_id" integer NOT NULL, "plan_key" text NOT NULL, "plan_name" text NOT NULL, "billing_type" text NOT NULL, "amount" integer NOT NULL, "currency" text NOT NULL, "provider" text NOT NULL, "mode" text NOT NULL, "price_id" text NULL, "public_key" text NULL, "credentials" text NULL, "profile_revision" integer NULL, "return_origin" text NOT NULL, "customer_ref" text NULL, "session_ref" text NULL, "subscription_ref" text NULL, "checkout_payload" text NULL, "state" text NOT NULL, "error_code" text NULL, "version" integer NOT NULL, "lease_until" integer NULL, "cancel_requested" boolean NOT NULL, "cancel_at" integer NULL, "cancel_event_at" integer NOT NULL, "created_at" integer NOT NULL, "updated_at" integer NOT NULL, FOREIGN KEY ("listing_id") REFERENCES "listings" ("id") ON DELETE RESTRICT, FOREIGN KEY ("owner_id") REFERENCES "users" ("id") ON DELETE RESTRICT, FOREIGN KEY ("approved_revision_id") REFERENCES "listing_revisions" ("id") ON DELETE RESTRICT, FOREIGN KEY ("plan_key") REFERENCES "publishing_plans" ("key") ON DELETE RESTRICT );
CREATE TABLE "publishing_receipts" ( "event_record_id" text NOT NULL PRIMARY KEY, "purchase_id" text NULL, "outcome" text NOT NULL, "applied_at" integer NOT NULL, FOREIGN KEY ("event_record_id") REFERENCES "publishing_events" ("id") ON DELETE RESTRICT, FOREIGN KEY ("purchase_id") REFERENCES "publishing_purchases" ("id") ON DELETE RESTRICT );
CREATE TABLE "publishing_references" ( "id" text NOT NULL PRIMARY KEY, "provider" text NOT NULL, "mode" text NOT NULL, "kind" text NOT NULL, "reference" text NOT NULL, "purchase_id" text NOT NULL, "payment_id" text NULL, FOREIGN KEY ("purchase_id") REFERENCES "publishing_purchases" ("id") ON DELETE RESTRICT, FOREIGN KEY ("payment_id") REFERENCES "publishing_payments" ("id") ON DELETE RESTRICT );
CREATE TABLE "publishing_slots" ( "listing_id" integer NOT NULL PRIMARY KEY, "purchase_id" text NOT NULL, FOREIGN KEY ("listing_id") REFERENCES "listings" ("id") ON DELETE RESTRICT, FOREIGN KEY ("purchase_id") REFERENCES "publishing_purchases" ("id") ON DELETE RESTRICT );
CREATE TABLE "remember_tokens" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" varchar NOT NULL, "selector" varchar NOT NULL, "token_hash" varchar NOT NULL, "expires_at" timestamp_text NOT NULL, "created_at" timestamp_text NOT NULL DEFAULT CURRENT_TIMESTAMP, "last_used_at" timestamp_text NULL );
CREATE TABLE "role_has_permissions" ( "permission_id" integer NOT NULL, "role_id" integer NOT NULL, PRIMARY KEY ("permission_id", "role_id"), FOREIGN KEY ("permission_id") REFERENCES "permissions" ("id") ON DELETE CASCADE, FOREIGN KEY ("role_id") REFERENCES "roles" ("id") ON DELETE CASCADE );
CREATE TABLE "roles" ( "id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "guard_name" varchar(255) NOT NULL, "created_at" datetime_text NULL, "updated_at" datetime_text NULL );
